<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';

use Prometheus\admin\AdminGuard;
use Prometheus\core\Database;
use Prometheus\core\PaperTrader;
use Prometheus\core\PaperStrategyEngine;
use Prometheus\evaluation\PaperTradingScenarioAnalyzer;
use Prometheus\prediction\Athena50CorrelationAnalyzer;

AdminGuard::requireAdmin();
if (session_status() === PHP_SESSION_NONE) session_start();
$symbol=prometheus_config('default_symbol','BTCUSDT');
$strategyModes=PaperStrategyEngine::modes();
$strategyDescriptions=[
    'PROMETHEUS'=>'Abre na direcao prevista em 15m; taxas e slippage entram no resultado da conta paper.',
    'MULTIHORIZON'=>'Opera quando pelo menos dois horizontes confirmam a direcao de 15m; nao espera amostra historica.',
    'INVERSE'=>'Inverte cada previsão direcional do PROMETHEUS. É a hipótese contrária para medir se o sinal funciona melhor ao avesso.',
    'MOMENTUM'=>'Segue EMA 9/26 em candles de 1m quando preço e tendência recente de 15m confirmam a mesma direção.',
    'MEAN_REVERSION'=>'Compra/vende nos extremos de Bollinger com RSI ate 35 ou a partir de 65; fecha ao voltar a media.',
    'BREAKOUT'=>'Opera rompimento do canal de 12 candles de 15m com volume igual ou acima da media.',
    'ADAPTIVE'=>'Usa momentum em tendencia, reversao em mercado lateral e rompimento em alta volatilidade.',
];
$requestedMode=(string)($_GET['mode']??'PROMETHEUS');
$mode=array_key_exists($requestedMode,$strategyModes)?$requestedMode:'PROMETHEUS';
$csrf=(string)($_SESSION['paper_trading_csrf']??'');
if($csrf===''){ $csrf=bin2hex(random_bytes(32)); $_SESSION['paper_trading_csrf']=$csrf; }
$notice=null;$error=null;$config=null;$account=null;$heartbeat=null;$priceRow=null;$predictions=[];$decisions=[];$trades=[];$curve=[];$btcPriceSeries=[];$forecastUp=[];$forecastDown=[];$forecastNeutral=[];$forecastHits=[];$forecastMisses=[];$forecastResultNeutral=[];$moduleSignals=[];$stats=[];$athenaStats=[];$athenaAblations=[];$candidateStats=[];$researchModes=[];$costScenarios=[];$featureCorrelation=[];$ready=true;$temporalSchemaReady=true;

if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['save_config'])){
    if(!isset($_POST['csrf'])||!hash_equals($csrf,(string)$_POST['csrf']))$error='A sessão expirou. Atualize a página e tente novamente.';
    else {
        $allocation=(float)($_POST['allocation_pct']??0);$fee=(float)($_POST['fee_pct']??0);$slippage=(float)($_POST['slippage_pct']??0);
        $minEdge=(float)($_POST['min_edge_pct']??0);$minConfidence=(float)($_POST['min_confidence']??0);
        $cooldown=(int)($_POST['cooldown_minutes']??0);$stop=(float)($_POST['stop_loss_pct']??0);$take=(float)($_POST['take_profit_pct']??0);
        $maxMinutes=(int)($_POST['max_position_minutes']??0);$initial=(float)($_POST['initial_balance']??100);
        if($allocation<=0||$allocation>50||$fee<0||$fee>5||$slippage<0||$slippage>5||$minEdge<0||$minConfidence<0||$minConfidence>1||$cooldown<0||$stop<0||$take<0||$maxMinutes<1||$initial<1)$error='Revise os limites: alocação 0–50%, custos até 5%, confiança 0–1 e saldo inicial positivo.';
        else {
            try{
                $existing=Database::fetch('SELECT position_side FROM paper_trading_v2_accounts WHERE mode=?',[$mode]);
                if($existing&&$existing['position_side']!=='FLAT'&&isset($_POST['initial_balance']))$error='O saldo inicial só pode ser alterado com a posição zerada.';
                else{
                    Database::execute('UPDATE paper_trading_config SET enabled=?,initial_balance=?,allocation_pct=?,allow_short=?,avoid_volatile=?,fee_pct=?,slippage_pct=?,min_edge_pct=?,min_confidence=?,cooldown_minutes=?,reversal_policy=?,stop_loss_pct=?,take_profit_pct=?,max_position_minutes=? WHERE mode=?',[
                        isset($_POST['enabled'])?1:0,$initial,$allocation,isset($_POST['allow_short'])?1:0,isset($_POST['avoid_volatile'])?1:0,$fee,$slippage,$minEdge,$minConfidence,$cooldown,
                        ($_POST['reversal_policy']??'CLOSE_REVERSE')==='CLOSE_ONLY'?'CLOSE_ONLY':'CLOSE_REVERSE',$stop,$take,$maxMinutes,$mode]);
                    $tradesExist=(int)(Database::fetch('SELECT COUNT(*) n FROM paper_trading_v2_trades WHERE mode=?',[$mode])['n']??0);
                    if(!$existing||($existing['position_side']==='FLAT'&&$tradesExist===0))Database::execute('UPDATE paper_trading_v2_accounts SET initial_balance=?,cash_balance=?,peak_equity=? WHERE mode=? AND position_side="FLAT"',[$initial,$initial,$initial,$mode]);
                    $notice='Configurações salvas para o modo '.$mode.'.';
                }
            }catch(Throwable $e){$error='Não foi possível salvar. Confirme se a migration 011 foi aplicada.';}
        }
    }
    $_SESSION['paper_trading_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['paper_trading_csrf'];
}

try{
    $config=Database::fetch('SELECT * FROM paper_trading_config WHERE mode=?',[$mode]);
    $account=Database::fetch('SELECT * FROM paper_trading_v2_accounts WHERE mode=?',[$mode]);
    $heartbeat=Database::fetch('SELECT *,TIMESTAMPDIFF(SECOND,last_finished_at,NOW()) AS age_seconds FROM paper_trading_heartbeat WHERE mode=?',[$mode]);
    $temporalColumns=Database::fetchAll('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME="market_data" AND COLUMN_NAME IN ("available_at","ingested_at","temporal_quality")');
    $temporalColumnNames=array_column($temporalColumns,'COLUMN_NAME');
    $temporalSchemaReady=count(array_intersect(['available_at','ingested_at','temporal_quality'],$temporalColumnNames))===3;
    if($temporalSchemaReady)$priceRow=Database::fetch('SELECT id,close_price,open_time,close_time,available_at,ingested_at FROM market_data WHERE symbol=? AND interval_name=? AND close_time<=NOW() AND ingested_at IS NOT NULL AND ingested_at<=UTC_TIMESTAMP() AND temporal_quality IN ("EXACT","INGESTION_ONLY") AND (available_at IS NULL OR (available_at<=UTC_TIMESTAMP() AND ingested_at>=available_at)) ORDER BY close_time DESC LIMIT 1',[$symbol,prometheus_config('collector.market_interval','1m')]);
    if(!$config||!$account||!$heartbeat||!$temporalSchemaReady){$ready=false;} else {
        $decisions=Database::fetchAll('SELECT * FROM paper_trading_decisions WHERE mode=? ORDER BY id DESC LIMIT 40',[$mode]);
        $trades=Database::fetchAll('SELECT * FROM paper_trading_v2_trades WHERE mode=? ORDER BY exit_at DESC,id DESC LIMIT 30',[$mode]);
        $curve=Database::fetchAll('SELECT id,prediction_id,price_timestamp,reference_price,equity FROM paper_trading_equity WHERE mode=? ORDER BY created_at DESC,id DESC LIMIT 720',[$mode]);$curve=array_reverse($curve);
        $priceHistory=Database::fetchAll('SELECT close_price,close_time FROM market_data WHERE symbol=? AND interval_name=? AND close_time<=NOW() AND ingested_at IS NOT NULL AND ingested_at<=UTC_TIMESTAMP() AND temporal_quality IN ("EXACT","INGESTION_ONLY") AND (available_at IS NULL OR (available_at<=UTC_TIMESTAMP() AND ingested_at>=available_at)) ORDER BY close_time DESC LIMIT 720',[$symbol,prometheus_config('collector.market_interval','1m')]);
        $priceHistory=array_reverse($priceHistory);
        foreach($priceHistory as $candle){$btcPriceSeries[]=['x'=>strtotime((string)$candle['close_time'])*1000,'y'=>(float)$candle['close_price'],'kind'=>'price'];}
        if($priceHistory){
            $chartStart=(string)$priceHistory[0]['close_time'];
            $chartPredictions=Database::fetchAll('SELECT p.id,p.created_at,p.target_time,p.initial_price,p.predicted_direction,p.probability_up,p.probability_down,p.confidence,r.final_price,r.actual_direction,r.directional_hit FROM predictions p LEFT JOIN prediction_results r ON r.prediction_id=p.id AND r.evaluation_version=2 WHERE p.symbol=? AND p.horizon="15m" AND p.created_at>=DATE_SUB(?,INTERVAL 15 MINUTE) AND p.created_at<=NOW() ORDER BY p.created_at ASC,p.id ASC LIMIT 1000',[$symbol,$chartStart]);
            foreach($chartPredictions as $forecast){
                $direction=(string)$forecast['predicted_direction'];
                $forecastPoint=['x'=>strtotime((string)$forecast['created_at'])*1000,'y'=>(float)$forecast['initial_price'],'kind'=>'forecast','prediction_id'=>(int)$forecast['id'],'direction'=>$direction,'probability_up'=>(float)$forecast['probability_up'],'probability_down'=>(float)$forecast['probability_down'],'confidence'=>(float)$forecast['confidence']];
                if($direction==='UP')$forecastUp[]=$forecastPoint;elseif($direction==='DOWN')$forecastDown[]=$forecastPoint;else $forecastNeutral[]=$forecastPoint;
                if($forecast['final_price']!==null&&$forecast['target_time']!==null){
                    $resultPoint=['x'=>strtotime((string)$forecast['target_time'])*1000,'y'=>(float)$forecast['final_price'],'kind'=>'result','prediction_id'=>(int)$forecast['id'],'direction'=>$direction,'actual'=>(string)$forecast['actual_direction'],'probability_up'=>(float)$forecast['probability_up'],'confidence'=>(float)$forecast['confidence']];
                    if($forecast['directional_hit']!==null){$resultPoint['hit']=(int)$forecast['directional_hit']===1;if($resultPoint['hit'])$forecastHits[]=$resultPoint;else $forecastMisses[]=$resultPoint;}
                    else $forecastResultNeutral[]=$resultPoint;
                }
            }
        }
        foreach(['15m','1h','4h','24h'] as $h){$r=Database::fetch('SELECT * FROM predictions WHERE symbol=? AND horizon=? AND created_at<=NOW() ORDER BY id DESC LIMIT 1',[$symbol,$h]);if($r)$predictions[$h]=$r;}
        $latest15=$predictions['15m']??null;
        if($latest15){
            $signalData=json_decode((string)$latest15['signals_json'],true)?:[];$weights=json_decode((string)$latest15['weights_json'],true)?:[];
            $present=[];$denominator=0.0;
            foreach($signalData as $s){if(($s['status']??'AVAILABLE')==='AVAILABLE'||($s['status']??'')==='STALE'){$w=(float)($weights[$s['module']]??1);$eff=$w*max(.05,(float)$s['confidence']);$denominator+=$eff;$present[$s['module']]=['signal'=>(float)$s['value'],'confidence'=>(float)$s['confidence'],'weight'=>$w,'effective'=>$eff,'contribution'=>(float)$s['value']*$eff,'status'=>(string)($s['status']??'AVAILABLE')];}}
            foreach($present as &$s)$s['contribution_share']=$denominator>0?$s['effective']/$denominator*100:0;unset($s);$moduleSignals=$present;
        }
        $stats=Database::fetch('SELECT COUNT(*) n,SUM(net_pnl>0) wins,SUM(net_pnl<0) losses,SUM(GREATEST(net_pnl,0)) gains,SUM(ABS(LEAST(net_pnl,0))) loss_sum,SUM(fees_usd) fees,SUM(slippage_usd) slippage,AVG(net_pnl) expectancy FROM paper_trading_v2_trades WHERE mode=?',[$mode])??[];
        foreach(array_keys($strategyModes) as $researchMode){$researchAccount=Database::fetch('SELECT * FROM paper_trading_v2_accounts WHERE mode=?',[$researchMode]);$researchConfig=Database::fetch('SELECT fee_pct,slippage_pct FROM paper_trading_config WHERE mode=?',[$researchMode])??[];$researchStats=Database::fetch('SELECT COUNT(*) n,SUM(net_pnl>0) wins,SUM(GREATEST(net_pnl,0)) gains,SUM(ABS(LEAST(net_pnl,0))) loss_sum,SUM(fees_usd+slippage_usd) costs FROM paper_trading_v2_trades WHERE mode=?',[$researchMode]);$researchPrice=(float)($priceRow['close_price']??0);$exitCostPct=(float)($researchConfig['fee_pct']??0)+(float)($researchConfig['slippage_pct']??0);$researchEquity=PaperTrader::markedEquity($researchAccount??[],$researchPrice,$exitCostPct);$researchInitial=(float)($researchAccount['initial_balance']??100);$researchModes[$researchMode]=['account'=>$researchAccount,'stats'=>$researchStats,'equity'=>$researchEquity,'net_pnl'=>$researchEquity-$researchInitial,'return_pct'=>$researchInitial>0?($researchEquity-$researchInitial)/$researchInitial*100:0.0];$allModeTrades=Database::fetchAll('SELECT side,entry_at,exit_at,entry_price,exit_price,quantity_btc,gross_pnl,fees_usd,slippage_usd,net_pnl FROM paper_trading_v2_trades WHERE mode=? ORDER BY exit_at ASC,id ASC',[$researchMode]);foreach(['LOW'=>0.5,'NORMAL'=>1.0,'STRESS'=>2.5] as $scenario=>$multiplier){$costScenarios[$researchMode][$scenario]=PaperTradingScenarioAnalyzer::analyze($allModeTrades,$researchInitial,$multiplier);}}
        uasort($researchModes,static fn(array $a,array $b):int=>($b['equity']<=>$a['equity']));
        try{
            $athenaStats=Database::fetchAll('SELECT s.horizon,s.regime,COUNT(*) n,AVG(p.probability_up) classic_mean_p,AVG(s.shadow_probability_up) shadow_mean_p,AVG(s.classic_hit) classic_accuracy,AVG(s.shadow_hit) shadow_accuracy,AVG(s.classic_brier) classic_brier,AVG(s.shadow_brier) shadow_brier,AVG(CASE WHEN s.actual_direction="UP" THEN -LN(GREATEST(0.000000001,s.shadow_probability_up)) WHEN s.actual_direction="DOWN" THEN -LN(GREATEST(0.000000001,1-s.shadow_probability_up)) ELSE NULL END) shadow_logloss,AVG(CASE WHEN s.actual_direction="UP" THEN -LN(GREATEST(0.000000001,p.probability_up)) WHEN s.actual_direction="DOWN" THEN -LN(GREATEST(0.000000001,1-p.probability_up)) ELSE NULL END) classic_logloss FROM athena50_shadow_predictions s JOIN predictions p ON p.id=s.prediction_id WHERE s.model_status IN ("READY","READY_PARTIAL") AND s.actual_direction IN ("UP","DOWN") GROUP BY s.horizon,s.regime ORDER BY FIELD(s.horizon,"15m","1h","4h","24h"),s.regime');
            $ablationRows=Database::fetchAll('SELECT horizon,regime,actual_direction,group_ablation_results FROM athena50_shadow_predictions WHERE model_status IN ("READY","READY_PARTIAL") AND actual_direction IN ("UP","DOWN") AND group_ablation_results IS NOT NULL');
            foreach($ablationRows as $ar){$byGroup=json_decode((string)$ar['group_ablation_results'],true)?:[];foreach($byGroup as $group=>$metric){if(!array_key_exists('hit',$metric))continue;$key=$ar['horizon'].'|'.$ar['regime'].'|'.$group;$athenaAblations[$key]??=['horizon'=>$ar['horizon'],'regime'=>$ar['regime'],'group'=>$group,'n'=>0,'directional_n'=>0,'hits'=>0,'brier_sum'=>0.0,'brier_n'=>0,'logloss_sum'=>0.0,'logloss_n'=>0];$athenaAblations[$key]['n']++;if($metric['hit']!==null){$athenaAblations[$key]['directional_n']++;$athenaAblations[$key]['hits']+=(int)$metric['hit'];}if(isset($metric['brier'])){$athenaAblations[$key]['brier_sum']+=(float)$metric['brier'];$athenaAblations[$key]['brier_n']++;}if(isset($metric['logloss'])){$athenaAblations[$key]['logloss_sum']+=(float)$metric['logloss'];$athenaAblations[$key]['logloss_n']++;}}}
            $candidateRows=Database::fetchAll('SELECT horizon,regime,actual_direction,candidate_results FROM athena50_shadow_predictions WHERE model_status IN ("READY","READY_PARTIAL") AND actual_direction IN ("UP","DOWN") AND candidate_results IS NOT NULL');
            foreach($candidateRows as $cr){$byModel=json_decode((string)$cr['candidate_results'],true)?:[];foreach($byModel as $model=>$metric){if(!array_key_exists('hit',$metric))continue;$key=$cr['horizon'].'|'.$cr['regime'].'|'.$model;$candidateStats[$key]??=['horizon'=>$cr['horizon'],'regime'=>$cr['regime'],'model'=>$model,'n'=>0,'directional_n'=>0,'hits'=>0,'brier_sum'=>0.0,'brier_n'=>0,'logloss_sum'=>0.0,'logloss_n'=>0];$candidateStats[$key]['n']++;if($metric['hit']!==null){$candidateStats[$key]['directional_n']++;$candidateStats[$key]['hits']+=(int)$metric['hit'];}if(isset($metric['brier'])){$candidateStats[$key]['brier_sum']+=(float)$metric['brier'];$candidateStats[$key]['brier_n']++;}if(isset($metric['logloss'])){$candidateStats[$key]['logloss_sum']+=(float)$metric['logloss'];$candidateStats[$key]['logloss_n']++;}}}
            $featureRows=Database::fetchAll('SELECT feature_vector FROM athena50_shadow_predictions WHERE model_status IN ("READY","READY_PARTIAL") ORDER BY prediction_created_at DESC LIMIT 1000');$featureSnapshots=[];foreach($featureRows as $fr){$features=json_decode((string)$fr['feature_vector'],true);if(is_array($features))$featureSnapshots[]=$features;}$featureCorrelation=Athena50CorrelationAnalyzer::analyzeSnapshots($featureSnapshots,.95,30);
        }catch(Throwable $ignored){$athenaStats=[];$athenaAblations=[];$candidateStats=[];$featureCorrelation=[];}
    }
}catch(Throwable $e){$ready=false;}

$price=(float)($priceRow['close_price']??0);$cash=(float)($account['cash_balance']??100);$qty=(float)($account['quantity_btc']??0);$side=(string)($account['position_side']??'FLAT');
$unrealized=$side==='FLAT'?0:($price-(float)$account['entry_price'])*$qty*($side==='LONG'?1:-1)-($qty*$price*((float)($config['fee_pct']??0)+(float)($config['slippage_pct']??0))/100);
$equity=\Prometheus\core\PaperTrader::markedEquity($account??[],$price,(float)($config['fee_pct']??0)+(float)($config['slippage_pct']??0));
$initial=(float)($account['initial_balance']??100);$realized=(float)($account['realized_pnl']??0);$totalPnl=$equity-$initial;$returnPct=$initial>0?$totalPnl/$initial*100:0;
$nTrades=(int)($stats['n']??0);$wins=(int)($stats['wins']??0);$lossSum=(float)($stats['loss_sum']??0);$profitFactor=$lossSum>0?(float)($stats['gains']??0)/$lossSum:null;$winRate=$nTrades>0?$wins/$nTrades*100:null;
$heartbeatAge=$heartbeat&&$heartbeat['last_finished_at']?(int)($heartbeat['age_seconds']??PHP_INT_MAX):PHP_INT_MAX;
$heartbeatStatus=!$ready?'MIGRATION PENDENTE':((int)($config['enabled']??0)===0?'PARADO':(($heartbeat['status']??'STOPPED')==='ERROR'?'ERRO':($heartbeatAge>300?'ATRASADO':'ATIVO')));
$decisionLabels=['OPEN_LONG'=>'ABRIR LONG','OPEN_SHORT'=>'ABRIR SHORT','CLOSE_LONG'=>'FECHAR LONG','CLOSE_SHORT'=>'FECHAR SHORT','HOLD_LONG'=>'MANTER LONG','HOLD_SHORT'=>'MANTER SHORT','NO_TRADE'=>'NÃO OPERAR','INDETERMINATE'=>'INDETERMINADA'];
$labels=['UP'=>'ALTA','DOWN'=>'BAIXA','INDETERMINATE'=>'INDEFINIDA','SIDEWAYS'=>'LATERAL (LEGADO)'];
$series=[];$buyHold=[];$startPrice=(float)($curve[0]['reference_price']??0);
foreach($curve as $point){$series[]=['x'=>strtotime((string)$point['price_timestamp'])*1000,'y'=>(float)$point['equity']];$buyHold[]=['x'=>strtotime((string)$point['price_timestamp'])*1000,'y'=>$startPrice>0?$initial*(float)$point['reference_price']/$startPrice:$initial];}
function ptMoney(float $n):string{return '$'.number_format($n,2,',','.');}
function ptPct(float $n):string{return ($n>0?'+':'').number_format($n,2,',','.').'%';}
?>
